insert into public.suggestions (title,category,city,area,description,cost_hint,tags,lat,lng,for_who) values
($q$miffy style, Tokyo Station$q$,$q$shopping$q$,$q$Tokyo$q$,$q$Marunouchi$q$,$q$Official Miffy shop on Character Street under Tokyo Station, with plush, stationery and Tokyo-only pieces like Stationmaster Miffy. Easy to drop into on arrival day or when catching a Shinkansen.$q$,$q$Free to browse$q$,array[$q$miffy$q$,$q$shop$q$,$q$kawaii$q$]::text[],35.6806,139.768,$q$sam$q$),
($q$Kiddy Land Harajuku$q$,$q$shopping$q$,$q$Tokyo$q$,$q$Omotesando$q$,$q$Several floors of character goods on Omotesando, run by the same company as the miffy style shops. Usually has Miffy and Ghibli corners. Busy at weekends, so go on a weekday morning.$q$,$q$Free to browse$q$,array[$q$miffy$q$,$q$ghibli$q$,$q$shop$q$,$q$kawaii$q$]::text[],35.6681,139.707,$q$sam$q$),
($q$Yayoi Kusama Museum$q$,$q$art$q$,$q$Tokyo$q$,$q$Shinjuku (Bentencho)$q$,$q$Kusama's own five-floor museum, with rotating shows, an infinity room when one is on, and pumpkins on the roof. Tickets are online only, for 90-minute slots, and go on sale at 10am JST on the 1st of the month two months ahead. That means 1 January for 29–31 March slots and 1 February for April. Usually closed Monday to Wednesday.$q$,$q$~¥1,100, timed tickets$q$,array[$q$kusama$q$,$q$art$q$,$q$booking$q$,$q$must-book$q$]::text[],35.7036,139.7262,$q$sam$q$),
($q$Nezu Museum & garden$q$,$q$art$q$,$q$Tokyo$q$,$q$Minami-Aoyama$q$,$q$Kengo Kuma building full of Japanese and East Asian art, opening onto a sloping hidden garden with teahouses and stone lanterns. There's a glass-walled café overlooking the garden. Book a timed slot online.$q$,$q$~¥1,300, timed tickets$q$,array[$q$art$q$,$q$garden$q$,$q$tea$q$,$q$traditional$q$,$q$booking$q$]::text[],35.6623,139.7171,$q$sam$q$),
($q$21_21 Design Sight$q$,$q$art$q$,$q$Tokyo$q$,$q$Roppongi$q$,$q$Tadao Ando gallery co-founded by Issey Miyake, with thoughtful, playful design exhibitions. It's small and calm, a good counterweight to the big Roppongi museums.$q$,$q$~¥1,600$q$,array[$q$design$q$,$q$art$q$,$q$architecture$q$]::text[],35.6664,139.7314,$q$sam$q$),
($q$Mori Art Museum$q$,$q$art$q$,$q$Tokyo$q$,$q$Roppongi Hills$q$,$q$Big contemporary art shows on the 53rd floor, paired with the Tokyo City View deck. It's open late most nights, so it works well as an evening plan after dinner.$q$,$q$~¥2,000$q$,array[$q$art$q$,$q$contemporary$q$,$q$night$q$,$q$views$q$]::text[],35.6604,139.7292,$q$both$q$),
($q$teamLab Planets$q$,$q$art$q$,$q$Tokyo$q$,$q$Toyosu$q$,$q$Barefoot digital art: you wade through knee-deep water rooms and a floating flower garden. It's popular rather than niche, but genuinely beautiful. Book a timed slot and wear shorts or trousers that roll up.$q$,$q$~¥4,000, book ahead$q$,array[$q$art$q$,$q$immersive$q$,$q$booking$q$]::text[],35.6491,139.7898,$q$sam$q$),
($q$Sumida Hokusai Museum$q$,$q$art$q$,$q$Tokyo$q$,$q$Ryogoku$q$,$q$Small, striking museum (designed by Kazuyo Sejima) for Hokusai, the Great Wave artist, in the neighbourhood where he lived. Pairs with Beer Club Popeye nearby for Josh.$q$,$q$~¥1,000$q$,array[$q$ukiyo-e$q$,$q$art$q$,$q$traditional$q$]::text[],35.6967,139.8008,$q$sam$q$),
($q$Ota Memorial Museum of Art$q$,$q$art$q$,$q$Tokyo$q$,$q$Harajuku$q$,$q$Tiny ukiyo-e woodblock print museum tucked behind Omotesando, where you take your shoes off at the door. Exhibitions change monthly and it closes between shows, so check dates.$q$,$q$~¥1,000$q$,array[$q$ukiyo-e$q$,$q$art$q$,$q$traditional$q$,$q$quiet$q$]::text[],35.669,139.705,$q$sam$q$),
($q$Tokyo National Museum$q$,$q$art$q$,$q$Tokyo$q$,$q$Ueno$q$,$q$Japan's oldest museum, with kimono, samurai armour, ceramics and screens. The Horyuji Treasures gallery is quietly stunning. Ueno Park's cherry blossom is right outside.$q$,$q$~¥1,000$q$,array[$q$art$q$,$q$traditional$q$,$q$history$q$]::text[],35.7188,139.7765,$q$sam$q$),
($q$Edo-Tokyo Open-Air Architectural Museum$q$,$q$sights$q$,$q$Tokyo$q$,$q$Koganei$q$,$q$Park full of rescued historic buildings: bathhouses, shops, farmhouses. Miyazaki sketched here for Spirited Away; the old bathhouse and the Takei Sanshodo stationery shop show up in the film's world. Easy to pair with the Ghibli Museum.$q$,$q$~¥400$q$,array[$q$ghibli$q$,$q$spirited-away$q$,$q$architecture$q$,$q$traditional$q$]::text[],35.7155,139.5134,$q$sam$q$),
($q$Donguri Kyowakoku (Ghibli shop)$q$,$q$shopping$q$,$q$Tokyo$q$,$q$Various$q$,$q$Studio Ghibli's official shop chain, with Totoro, Kiki and No-Face goods, much of it not sold abroad. There are branches in most big cities and stations, so look up the nearest one on the day.$q$,$q$Free to browse$q$,array[$q$ghibli$q$,$q$shop$q$,$q$totoro$q$]::text[],null,null,$q$sam$q$),
($q$Laputa Asagaya$q$,$q$art$q$,$q$Tokyo$q$,$q$Asagaya$q$,$q$Ivy-covered little cinema named after Castle in the Sky, showing mostly 1950s–60s Japanese films. Usually there are no subtitles, but the building and posters are worth it. Asagaya's covered shopping street is lovely too.$q$,$q$~¥1,400$q$,array[$q$film$q$,$q$cinema$q$,$q$ghibli$q$,$q$retro$q$]::text[],35.7062,139.6352,$q$sam$q$),
($q$National Film Archive of Japan$q$,$q$art$q$,$q$Tokyo$q$,$q$Kyobashi$q$,$q$Japan's national film archive. Its exhibition floor covers Japanese cinema history through old cameras, posters and props, and it also runs screenings of restored classics.$q$,$q$~¥250$q$,array[$q$film$q$,$q$cinema$q$,$q$history$q$]::text[],35.6761,139.7704,$q$sam$q$),
($q$JCII Camera Museum$q$,$q$art$q$,$q$Tokyo$q$,$q$Ichibancho$q$,$q$Small museum near Hanzomon with a huge collection of historic Japanese cameras, from wooden plate cameras to Nikon Fs. There's a photo gallery downstairs.$q$,$q$Small fee$q$,array[$q$film-camera$q$,$q$museum$q$,$q$photography$q$]::text[],35.6857,139.7413,$q$sam$q$),
($q$Fujiya Camera, Nakano$q$,$q$shopping$q$,$q$Tokyo$q$,$q$Nakano$q$,$q$Long-running used camera dealer by Nakano station, with honest condition grades and plenty of film bodies and lenses. It's right next to Nakano Broadway, so Sam does cameras while Josh does toys.$q$,$q$Varies$q$,array[$q$film-camera$q$,$q$used$q$,$q$shop$q$]::text[],35.7075,139.6655,$q$sam$q$),
($q$Map Camera, Shinjuku$q$,$q$shopping$q$,$q$Tokyo$q$,$q$Shinjuku$q$,$q$Multi-floor used camera store near Shinjuku West Exit. The basement is the film and Leica floor. English-speaking staff, tax-free, and no haggling.$q$,$q$Varies$q$,array[$q$film-camera$q$,$q$used$q$,$q$leica$q$,$q$shop$q$]::text[],35.6913,139.6963,$q$sam$q$),
($q$Popeye Camera, Jiyugaoka$q$,$q$shopping$q$,$q$Tokyo$q$,$q$Jiyugaoka$q$,$q$Decades-old film shop with rare film stock, developing, and cute washi tape, albums and stationery. Usually closed Wednesdays. Wander Jiyugaoka's cafés afterwards.$q$,$q$Cheap–mid$q$,array[$q$film$q$,$q$film-camera$q$,$q$developing$q$,$q$stationery$q$]::text[],35.6079,139.6683,$q$sam$q$),
($q$Jiyugaoka$q$,$q$coffee$q$,$q$Tokyo$q$,$q$Jiyugaoka$q$,$q$Leafy, slow neighbourhood full of patisseries, homeware shops and small cafés. A gentle half-day with zero tourist crowds.$q$,$q$Cheap–mid$q$,array[$q$cozy$q$,$q$cafes$q$,$q$walk$q$,$q$sweets$q$]::text[],35.6073,139.6688,$q$both$q$),
($q$Nakajima-no-Ochaya, Hama-rikyu$q$,$q$tea$q$,$q$Tokyo$q$,$q$Shiodome$q$,$q$Matcha and a wagashi sweet in a teahouse on a pond, inside a former shogun's garden, with skyscrapers behind. One of Tokyo's best quiet contrasts.$q$,$q$~¥300 garden + matcha set$q$,array[$q$tea$q$,$q$garden$q$,$q$traditional$q$]::text[],35.6597,139.7631,$q$sam$q$),
($q$Sakurai Japanese Tea Experience$q$,$q$tea$q$,$q$Tokyo$q$,$q$Omotesando$q$,$q$Minimalist tea bar where a tea master roasts leaves at the counter and walks you through a tasting course. Book ahead for the course.$q$,$q$¥¥¥$q$,array[$q$tea$q$,$q$tasting$q$,$q$counter$q$,$q$booking$q$]::text[],35.664,139.711,$q$sam$q$),
($q$Kagurazaka$q$,$q$sights$q$,$q$Tokyo$q$,$q$Kagurazaka$q$,$q$Old geisha district with stone-paved back lanes, tiny restaurants and a French twist (lots of bistros). Lovely at dusk.$q$,$q$Free$q$,array[$q$traditional$q$,$q$walk$q$,$q$cozy$q$,$q$alleys$q$]::text[],35.702,139.7406,$q$both$q$),
($q$Gotokuji Temple$q$,$q$sights$q$,$q$Tokyo$q$,$q$Setagaya$q$,$q$Temple said to be the home of the maneki-neko beckoning cat, with thousands of little white cat figures. Quiet suburban temple, and a short ride on the Setagaya tram line.$q$,$q$Free$q$,array[$q$traditional$q$,$q$cats$q$,$q$temple$q$,$q$quiet$q$]::text[],35.6489,139.6474,$q$sam$q$),
($q$Rikugien Garden$q$,$q$nature$q$,$q$Tokyo$q$,$q$Komagome$q$,$q$Classic Edo strolling garden with a huge weeping cherry tree that's lit up at night during blossom season.$q$,$q$~¥300$q$,array[$q$garden$q$,$q$sakura$q$,$q$traditional$q$,$q$night$q$]::text[],35.733,139.7469,$q$sam$q$),
($q$Koishikawa Korakuen$q$,$q$nature$q$,$q$Tokyo$q$,$q$Iidabashi$q$,$q$One of Tokyo's oldest gardens, with a red bridge, ponds and weeping cherries. Much quieter than Ueno or Meguro.$q$,$q$~¥300$q$,array[$q$garden$q$,$q$sakura$q$,$q$traditional$q$]::text[],35.7055,139.7497,$q$sam$q$),
($q$Shinjuku Gyoen$q$,$q$nature$q$,$q$Tokyo$q$,$q$Shinjuku$q$,$q$Huge garden with 1,000+ cherry trees of many varieties, so something's usually blooming. No alcohol allowed. In peak season it may need advance timed tickets.$q$,$q$~¥500$q$,array[$q$sakura$q$,$q$park$q$,$q$picnic$q$]::text[],35.6852,139.7101,$q$both$q$),
($q$Kiyosumi-Shirakawa$q$,$q$coffee$q$,$q$Tokyo$q$,$q$Koto$q$,$q$Warehouse district turned coffee neighbourhood (Blue Bottle's first Japan café is here), with small galleries and the lovely Kiyosumi Garden.$q$,$q$Cheap–mid$q$,array[$q$coffee$q$,$q$gallery$q$,$q$garden$q$,$q$cozy$q$]::text[],35.681,139.799,$q$both$q$),
($q$Kappabashi Kitchen Street$q$,$q$shopping$q$,$q$Tokyo$q$,$q$Asakusa$q$,$q$Street of trade shops selling knives, ceramics, lanterns and those plastic food models. Great for real souvenirs.$q$,$q$Free to browse$q$,array[$q$knives$q$,$q$ceramics$q$,$q$plastic-food$q$]::text[],35.713,139.788,$q$both$q$),
($q$Kosugi-yu bathhouse$q$,$q$sights$q$,$q$Tokyo$q$,$q$Koenji$q$,$q$A beautiful old public bathhouse from the 1930s with a temple-style roof. Hot baths with locals, then beers in Koenji. Bring a small towel.$q$,$q$~¥550$q$,array[$q$sento$q$,$q$traditional$q$,$q$local$q$]::text[],35.707,139.651,$q$both$q$),
($q$Tsukiji Outer Market breakfast$q$,$q$food$q$,$q$Tokyo$q$,$q$Tsukiji$q$,$q$The wholesale fish market moved, but the outer market's stalls remain: tamagoyaki on a stick, sushi counters and knife shops. Go early, around 8am.$q$,$q$Cheap–mid$q$,array[$q$breakfast$q$,$q$seafood$q$,$q$market$q$]::text[],35.6655,139.7707,$q$both$q$),
($q$Fuunji tsukemen$q$,$q$food$q$,$q$Tokyo$q$,$q$Shinjuku$q$,$q$Cult dipping-noodle shop near Shinjuku Station, with thick noodles and a rich chicken-and-fish broth. There's always a queue; it moves.$q$,$q$~¥1,100$q$,array[$q$ramen$q$,$q$queue$q$]::text[],35.687,139.697,$q$both$q$),
($q$Butagumi tonkatsu$q$,$q$food$q$,$q$Tokyo$q$,$q$Nishi-Azabu$q$,$q$Tonkatsu in an old house, where you choose your pork by breed and farm. Possibly the best katsu of your life. Book ahead.$q$,$q$~¥3,000$q$,array[$q$tonkatsu$q$,$q$dinner$q$]::text[],35.659,139.723,$q$both$q$),
($q$Yurakucho izakaya under the tracks$q$,$q$food$q$,$q$Tokyo$q$,$q$Yurakucho$q$,$q$Smoky yakitori and beer joints tucked into the brick arches under the train line between Yurakucho and Shimbashi. Very salaryman, very fun.$q$,$q$Cheap$q$,array[$q$izakaya$q$,$q$yakitori$q$,$q$alley$q$,$q$local$q$]::text[],35.674,139.763,$q$both$q$),
($q$Tsukishima Monja Street$q$,$q$food$q$,$q$Tokyo$q$,$q$Tsukishima$q$,$q$Street lined with monjayaki restaurants, a gooey Tokyo cousin of okonomiyaki that you cook yourselves on a hotplate. Messy and great.$q$,$q$Cheap$q$,array[$q$monjayaki$q$,$q$dinner$q$,$q$local$q$]::text[],35.6635,139.784,$q$both$q$),
($q$Isetan Shinjuku depachika$q$,$q$food$q$,$q$Tokyo$q$,$q$Shinjuku$q$,$q$Basement food hall of dreams: bento, wagashi and fancy fruit. Build a hanami picnic for Shinjuku Gyoen.$q$,$q$Cheap–mid$q$,array[$q$food-hall$q$,$q$sweets$q$,$q$picnic$q$]::text[],35.6919,139.7046,$q$both$q$),
($q$Bar Benfiddich$q$,$q$drinks$q$,$q$Tokyo$q$,$q$Shinjuku$q$,$q$Tiny world-famous bar where the bartender grinds herbs and spirits by hand. Small and seated, so arrive at opening or expect a wait.$q$,$q$¥¥¥$q$,array[$q$cocktails$q$,$q$bar$q$,$q$special$q$]::text[],35.6911,139.6982,$q$both$q$),
($q$JBS (Jazz, Blues & Soul)$q$,$q$drinks$q$,$q$Tokyo$q$,$q$Shibuya$q$,$q$Tiny Shibuya listening bar lined with thousands of the owner's records. Order a whisky and just listen.$q$,$q$~¥1,000/drink$q$,array[$q$vinyl$q$,$q$bar$q$,$q$music$q$,$q$cozy$q$]::text[],35.6602,139.6977,$q$both$q$),
($q$Hitachino Brewing Lab$q$,$q$drinks$q$,$q$Tokyo$q$,$q$Akihabara$q$,$q$Owl-logo brewery's taproom in a converted railway viaduct between Akihabara and Kanda. A perfect reset after the retro game shops.$q$,$q$~¥1,000/glass$q$,array[$q$craft-beer$q$]::text[],35.698,139.771,$q$both$q$),
($q$Mikkeller Tokyo$q$,$q$drinks$q$,$q$Tokyo$q$,$q$Shibuya$q$,$q$Small two-floor craft beer bar up the hill from Shibuya. Great tap list including Japanese collabs.$q$,$q$~¥1,000+/glass$q$,array[$q$craft-beer$q$]::text[],35.657,139.696,$q$both$q$),
($q$Spring Valley Brewery$q$,$q$drinks$q$,$q$Tokyo$q$,$q$Daikanyama$q$,$q$Kirin's craft brewpub under the tracks at Log Road Daikanyama, with tasting flights and good food pairings.$q$,$q$~¥1,000/glass$q$,array[$q$craft-beer$q$,$q$food$q$]::text[],35.6495,139.703,$q$both$q$),
($q$Fuglen Tokyo$q$,$q$coffee$q$,$q$Tokyo$q$,$q$Tomigaya$q$,$q$Oslo café with 1960s Norwegian furniture. Great light-roast coffee by day, cocktails by night. Yoyogi Park is round the corner.$q$,$q$~¥600$q$,array[$q$coffee$q$,$q$cocktails$q$,$q$vintage$q$]::text[],35.6676,139.6914,$q$both$q$),
($q$Glitch Coffee & Roasters$q$,$q$coffee$q$,$q$Tokyo$q$,$q$Jimbocho$q$,$q$Excellent single-origin pour-overs, among Tokyo's best. Fits a Jimbocho bookshop morning.$q$,$q$~¥800$q$,array[$q$coffee$q$,$q$specialty$q$]::text[],35.6939,139.7609,$q$both$q$),
($q$Tokyo Video Gamers barcade$q$,$q$retro$q$,$q$Tokyo$q$,$q$Akihabara$q$,$q$Retro game bar near Akihabara Electric Town exit, with licensed SEGA, SNK and Data East games to play while you drink. Usually open 11am–11pm.$q$,$q$Drinks ~¥1,000$q$,array[$q$arcade$q$,$q$bar$q$,$q$games$q$]::text[],35.699,139.7705,$q$josh$q$),
($q$Mandarake Complex$q$,$q$retro$q$,$q$Tokyo$q$,$q$Akihabara$q$,$q$Eight floors of collectables, including a whole retro-game and vintage toy floor. A different vibe from Super Potato and often better prices.$q$,$q$Free to browse$q$,array[$q$games$q$,$q$toys$q$,$q$shop$q$,$q$collectors$q$]::text[],35.7008,139.77,$q$josh$q$),
($q$BEEP Akihabara$q$,$q$retro$q$,$q$Tokyo$q$,$q$Akihabara$q$,$q$Specialist in retro Japanese computers and consoles (PC-98, MSX, Mega Drive). Deep cuts you won't find elsewhere.$q$,$q$Free to browse$q$,array[$q$games$q$,$q$retro-pc$q$,$q$shop$q$]::text[],35.6996,139.7718,$q$josh$q$),
($q$Akihabara Gachapon Hall$q$,$q$retro$q$,$q$Tokyo$q$,$q$Akihabara$q$,$q$Hundreds of capsule toy machines in one room. Dangerous with a pocket of ¥100 coins.$q$,$q$¥300–500 a go$q$,array[$q$gachapon$q$,$q$toys$q$,$q$fun$q$]::text[],35.7,139.7712,$q$both$q$),
($q$Radio Kaikan$q$,$q$retro$q$,$q$Tokyo$q$,$q$Akihabara$q$,$q$Akihabara's landmark building with ten floors of figure, model kit, trading card and toy shops.$q$,$q$Free to browse$q$,array[$q$figures$q$,$q$toys$q$,$q$shop$q$]::text[],35.6985,139.7717,$q$both$q$),
($q$Hard Off / Book Off (suburbs)$q$,$q$retro$q$,$q$Tokyo$q$,$q$Various$q$,$q$Second-hand chains that are a treasure hunt for retro consoles, Game Boys and 'junk' bins. The suburban branches you pass on drive days are the best.$q$,$q$Cheap$q$,array[$q$games$q$,$q$junk$q$,$q$used$q$,$q$needs-car$q$]::text[],null,null,$q$josh$q$),
($q$Nissan Crossing, Ginza$q$,$q$cars$q$,$q$Tokyo$q$,$q$Ginza$q$,$q$Nissan's glass showroom on Ginza's main crossing, with concept and heritage cars on rotation and a café upstairs. Quick and free.$q$,$q$Free$q$,array[$q$showroom$q$,$q$nissan$q$,$q$concept-cars$q$]::text[],35.6716,139.765,$q$josh$q$),
($q$Shuto Expressway night loop$q$,$q$drive$q$,$q$Tokyo$q$,$q$Shuto$q$,$q$The real Wangan Midnight drive: the C1 inner loop, over Rainbow Bridge, out along the Bayshore. Do it legally and in the left lane, and get an ETC card with the rental.$q$,$q$Tolls ~¥1,000–2,000$q$,array[$q$night$q$,$q$drive$q$,$q$wangan$q$,$q$needs-car$q$]::text[],35.63,139.78,$q$josh$q$),
($q$Nissan Engine Museum$q$,$q$cars$q$,$q$Yokohama$q$,$q$Kanagawa-ku$q$,$q$Nissan's original Yokohama plant building with a hall of historic and racing engines. Free, weekdays only (closed weekends), and the factory tour needs booking.$q$,$q$Free$q$,array[$q$museum$q$,$q$engines$q$,$q$nissan$q$,$q$weekday$q$]::text[],35.4865,139.6505,$q$josh$q$),
($q$Cup Noodles Museum$q$,$q$sights$q$,$q$Yokohama$q$,$q$Minatomirai$q$,$q$Design your own cup noodle packaging and pick the flavours, then take it home in an inflated bag. Silly and great.$q$,$q$~¥500 + ¥500 to design a cup$q$,array[$q$fun$q$,$q$food$q$,$q$hands-on$q$]::text[],35.4552,139.6384,$q$both$q$),
($q$Sankeien Garden$q$,$q$nature$q$,$q$Yokohama$q$,$q$Honmoku$q$,$q$Big landscaped garden with historic buildings moved from Kyoto and Kamakura, including a three-storey pagoda over a pond. Gorgeous in blossom season.$q$,$q$~¥900$q$,array[$q$garden$q$,$q$traditional$q$,$q$sakura$q$,$q$architecture$q$]::text[],35.418,139.665,$q$sam$q$),
($q$Kamakura & Enoden line$q$,$q$sights$q$,$q$Kanagawa$q$,$q$Kamakura$q$,$q$Great Buddha, bamboo-garden temples, then the little Enoden train along the coast to Enoshima. A good day trip from Tokyo.$q$,$q$Cheap$q$,array[$q$temples$q$,$q$seaside$q$,$q$retro-train$q$]::text[],35.3167,139.5358,$q$both$q$),
($q$Route 134 Shonan coast drive$q$,$q$drive$q$,$q$Kanagawa$q$,$q$Shonan$q$,$q$Seaside road from Kamakura past Enoshima toward Oiso, with surf town cafés and Fuji views on clear days. Easy run to start a Hakone drive day.$q$,$q$Free$q$,array[$q$coast$q$,$q$drive$q$,$q$needs-car$q$]::text[],35.31,139.48,$q$josh$q$),
($q$Hakone Open-Air Museum$q$,$q$art$q$,$q$Hakone / Fuji$q$,$q$Ninotaira$q$,$q$Sculpture park in the mountains: Henry Moore, a Picasso pavilion and a hot-spring foot bath. Great for a drive day stop.$q$,$q$~¥2,000$q$,array[$q$art$q$,$q$sculpture$q$,$q$outdoors$q$,$q$picasso$q$]::text[],35.2449,139.0507,$q$sam$q$),
($q$Pola Museum of Art$q$,$q$art$q$,$q$Hakone / Fuji$q$,$q$Sengokuhara$q$,$q$Glass museum sunk into a beech forest, with Monet, Renoir and modern Japanese works, plus a nice forest walking trail.$q$,$q$~¥1,800$q$,array[$q$art$q$,$q$impressionists$q$,$q$forest$q$]::text[],35.265,139.043,$q$sam$q$),
($q$Hakone Shrine lakeside torii$q$,$q$sights$q$,$q$Hakone / Fuji$q$,$q$Lake Ashi$q$,$q$Cedar-lined shrine with a red torii gate standing in the lake. Go early before the photo queue.$q$,$q$Free$q$,array[$q$shrine$q$,$q$traditional$q$,$q$lake$q$]::text[],35.205,139.025,$q$both$q$),
($q$Chureito Pagoda at dawn$q$,$q$sights$q$,$q$Hakone / Fuji$q$,$q$Fujiyoshida$q$,$q$The classic pagoda, cherry blossom and Fuji shot. It's busy, so go at sunrise. Around 400 steps up.$q$,$q$Free$q$,array[$q$sakura$q$,$q$fuji$q$,$q$early$q$]::text[],35.5013,138.802,$q$both$q$),
($q$Shuzenji onsen town$q$,$q$sights$q$,$q$Hakone / Fuji$q$,$q$Izu$q$,$q$Small onsen town with a riverside bamboo path, red bridges and an old temple. Quiet end point after the Izu Skyline.$q$,$q$Cheap$q$,array[$q$onsen$q$,$q$bamboo$q$,$q$traditional$q$]::text[],34.97,138.929,$q$both$q$),
($q$Jogasaki Coast$q$,$q$nature$q$,$q$Hakone / Fuji$q$,$q$Izu$q$,$q$Volcanic cliffs and a swaying suspension bridge over the sea on the east Izu coast. Good leg-stretch on a drive day.$q$,$q$Free$q$,array[$q$coast$q$,$q$walk$q$,$q$suspension-bridge$q$]::text[],34.9,139.136,$q$both$q$),
($q$Matsumoto City Museum of Art (Kusama)$q$,$q$art$q$,$q$Nagano$q$,$q$Matsumoto$q$,$q$Kusama's hometown museum: polka-dot exterior, flower sculpture and a big permanent Kusama collection. About 3 hours' drive from Tokyo; combine with Matsumoto Castle for a full Sam day.$q$,$q$~¥410+$q$,array[$q$kusama$q$,$q$art$q$,$q$daytrip$q$,$q$needs-car$q$]::text[],36.234,137.976,$q$sam$q$),
($q$Matsumoto Castle$q$,$q$sights$q$,$q$Nagano$q$,$q$Matsumoto$q$,$q$One of Japan's few original castles, black-walled with the Alps behind. Its cherry blossom is usually early-mid April.$q$,$q$~¥700$q$,array[$q$castle$q$,$q$traditional$q$,$q$sakura$q$]::text[],36.2385,137.969,$q$both$q$),
($q$Jigokudani Snow Monkey Park$q$,$q$nature$q$,$q$Nagano$q$,$q$Yamanouchi$q$,$q$Wild macaques soaking in hot springs. In early April the snow is mostly gone but the monkeys are still there. It's a big detour, and only worth it if Sam really wants it.$q$,$q$~¥800$q$,array[$q$wildlife$q$,$q$monkeys$q$,$q$onsen$q$,$q$daytrip$q$]::text[],36.733,138.462,$q$sam$q$),
($q$Ghibli Park$q$,$q$art$q$,$q$Nagoya$q$,$q$Nagakute$q$,$q$Life-size Ghibli worlds: Satsuki and Mei's house, the Grand Warehouse and Howl's Castle area. Overseas day passes go on sale on the 10th, two months ahead, at 2pm JST, so 10 February for an April visit. It's ten minutes from the Toyota Automobile Museum, so both of you win that day.$q$,$q$Day pass, book ahead$q$,array[$q$ghibli$q$,$q$booking$q$,$q$must-book$q$,$q$totoro$q$]::text[],35.172,137.088,$q$sam$q$),
($q$Toyota Kaikan + plant tour$q$,$q$cars$q$,$q$Nagoya$q$,$q$Toyota City$q$,$q$Watch cars being built on a real Toyota line. Tours are free, weekdays only, and book up: reserve two weeks to three months ahead on Toyota's site, with limited English slots.$q$,$q$Free, booking required$q$,array[$q$toyota$q$,$q$factory$q$,$q$booking$q$,$q$weekday$q$]::text[],35.0573,137.157,$q$josh$q$),
($q$SCMaglev & Railway Park$q$,$q$sights$q$,$q$Nagoya$q$,$q$Kinjo-futo$q$,$q$JR Central's museum with record-breaking maglevs, every generation of Shinkansen and a driving simulator.$q$,$q$~¥1,000$q$,array[$q$trains$q$,$q$maglev$q$,$q$shinkansen$q$]::text[],35.045,136.849,$q$josh$q$),
($q$Meiji Mura$q$,$q$sights$q$,$q$Nagoya$q$,$q$Inuyama$q$,$q$Open-air museum of Meiji-era buildings, including the lobby of Frank Lloyd Wright's Imperial Hotel, with steam trains and old trams. Feels like walking through a film set.$q$,$q$~¥2,000$q$,array[$q$architecture$q$,$q$history$q$,$q$film-sets$q$,$q$needs-car$q$]::text[],35.348,136.989,$q$both$q$),
($q$Inuyama Castle & old town$q$,$q$sights$q$,$q$Nagoya$q$,$q$Inuyama$q$,$q$Original 1500s castle above the river, with a charming castle-town street of sweets and sake shops below.$q$,$q$~¥550$q$,array[$q$castle$q$,$q$traditional$q$,$q$sakura$q$]::text[],35.3883,136.9393,$q$both$q$),
($q$Tokugawa Art Museum$q$,$q$art$q$,$q$Nagoya$q$,$q$Higashi-ku$q$,$q$Treasures of the Owari Tokugawa lords: samurai armour, tea ceremony utensils, Noh costumes, plus a lovely Japanese garden next door (Tokugawaen).$q$,$q$~¥1,600$q$,array[$q$art$q$,$q$samurai$q$,$q$traditional$q$]::text[],35.186,136.933,$q$sam$q$),
($q$Atsuta Jingu$q$,$q$sights$q$,$q$Nagoya$q$,$q$Atsuta$q$,$q$One of Japan's most important shrines, set in a deep forest of huge camphor trees. Pair with hitsumabushi next door.$q$,$q$Free$q$,array[$q$shrine$q$,$q$traditional$q$,$q$forest$q$]::text[],35.1279,136.9087,$q$both$q$),
($q$Hitsumabushi at Atsuta Horaiken$q$,$q$food$q$,$q$Nagoya$q$,$q$Atsuta$q$,$q$Nagoya's grilled eel on rice, eaten three ways: plain, with condiments, then as a broth. The original restaurant, and it queues.$q$,$q$~¥4,500$q$,array[$q$eel$q$,$q$dinner$q$,$q$local-specialty$q$]::text[],35.126,136.909,$q$both$q$),
($q$Miso katsu at Yabaton$q$,$q$food$q$,$q$Nagoya$q$,$q$Yabacho$q$,$q$Pork cutlet drowned in sweet red miso sauce, Nagoya's signature dish.$q$,$q$~¥1,500$q$,array[$q$tonkatsu$q$,$q$local-specialty$q$]::text[],35.1615,136.906,$q$both$q$),
($q$Nagoya 'morning' kissaten$q$,$q$coffee$q$,$q$Nagoya$q$,$q$Osu$q$,$q$Nagoya cafés give you free toast, egg and sometimes more with your morning coffee. Find an old kissaten near Osu and order before 11.$q$,$q$~¥500$q$,array[$q$kissaten$q$,$q$breakfast$q$,$q$local$q$]::text[],35.159,136.904,$q$both$q$),
($q$Arashiyama Miffy Sakura Kitchen$q$,$q$food$q$,$q$Kyoto$q$,$q$Arashiyama$q$,$q$Miffy bakery and shop on Arashiyama's main street, selling Miffy-face buns and pastries plus Kyoto-only Miffy goods. Go before the midday crowds.$q$,$q$Under ¥1,000$q$,array[$q$miffy$q$,$q$bakery$q$,$q$kawaii$q$]::text[],35.0155,135.6775,$q$sam$q$),
($q$Arashiyama Monkey Park Iwatayama$q$,$q$nature$q$,$q$Kyoto$q$,$q$Arashiyama$q$,$q$Wild macaques roaming free on a hilltop with a view over Kyoto. It's a steep 20-minute climb. Don't stare them in the eye.$q$,$q$~¥600$q$,array[$q$wildlife$q$,$q$monkeys$q$,$q$views$q$]::text[],35.01,135.6772,$q$sam$q$),
($q$Okochi Sanso villa$q$,$q$tea$q$,$q$Kyoto$q$,$q$Arashiyama$q$,$q$Hillside garden and villa of 1920s–30s samurai-film star Denjiro Okochi. Matcha and a sweet are included with entry. Film plus tea plus garden, very Sam.$q$,$q$~¥1,000 incl. matcha$q$,array[$q$tea$q$,$q$garden$q$,$q$film$q$,$q$traditional$q$]::text[],35.017,135.67,$q$sam$q$),
($q$Arashiyama bamboo grove at dawn$q$,$q$nature$q$,$q$Kyoto$q$,$q$Arashiyama$q$,$q$Magical when empty, unbearable by 10am. Be there by 7, then Miffy buns.$q$,$q$Free$q$,array[$q$bamboo$q$,$q$early$q$,$q$walk$q$]::text[],35.017,135.672,$q$both$q$),
($q$Ippodo Tea main store$q$,$q$tea$q$,$q$Kyoto$q$,$q$Teramachi$q$,$q$300-year-old tea merchant. The Kaboku tearoom lets you whisk your own matcha and taste gyokuro. The best place to buy tea to take home.$q$,$q$~¥1,500 tearoom$q$,array[$q$tea$q$,$q$matcha$q$,$q$shop$q$]::text[],35.0136,135.7676,$q$sam$q$),
($q$Kawai Kanjiro's House$q$,$q$art$q$,$q$Kyoto$q$,$q$Higashiyama$q$,$q$Home and kiln of a great 20th-century potter, preserved as he left it, with his furniture, pots and climbing kiln. Peaceful. Closed Mondays.$q$,$q$~¥900$q$,array[$q$ceramics$q$,$q$mingei$q$,$q$traditional$q$,$q$quiet$q$]::text[],34.9935,135.7745,$q$sam$q$),
($q$Toei Kyoto Studio Park$q$,$q$sights$q$,$q$Kyoto$q$,$q$Uzumasa$q$,$q$A working film studio backlot for samurai dramas: Edo streets, ninja shows, and sometimes real shoots. Cinema history you can walk through.$q$,$q$~¥2,400$q$,array[$q$film$q$,$q$samurai$q$,$q$sets$q$]::text[],35.017,135.709,$q$sam$q$),
($q$Daitokuji sub-temples$q$,$q$sights$q$,$q$Kyoto$q$,$q$Kita-ku$q$,$q$A walled complex of Zen temples where the tea ceremony grew up. Daisen-in and Koto-in have extraordinary small gardens. Calm even in peak season.$q$,$q$~¥500 each$q$,array[$q$zen$q$,$q$gardens$q$,$q$tea$q$,$q$traditional$q$]::text[],35.044,135.746,$q$sam$q$),
($q$Kiyomizu-yaki pottery workshop$q$,$q$art$q$,$q$Kyoto$q$,$q$Gojozaka$q$,$q$Paint or throw your own Kyoto-style bowl in the old pottery lanes below Kiyomizu-dera. They glaze and ship it home.$q$,$q$~¥3,000$q$,array[$q$ceramics$q$,$q$hands-on$q$,$q$traditional$q$,$q$booking$q$]::text[],34.996,135.778,$q$sam$q$),
($q$Heian Shrine garden$q$,$q$nature$q$,$q$Kyoto$q$,$q$Okazaki$q$,$q$The garden behind the big red shrine has famous weeping cherries over the pond, and the stepping stones across it appear in Lost in Translation. Best in early April.$q$,$q$~¥600$q$,array[$q$sakura$q$,$q$garden$q$,$q$traditional$q$]::text[],35.016,135.782,$q$sam$q$),
($q$Ohara & Sanzen-in$q$,$q$nature$q$,$q$Kyoto$q$,$q$Ohara$q$,$q$Rural valley north of Kyoto with mossy temple gardens and little stone statues peeking out of the moss. Feels like a Ghibli countryside.$q$,$q$~¥700$q$,array[$q$moss$q$,$q$temple$q$,$q$rural$q$,$q$quiet$q$]::text[],35.12,135.834,$q$sam$q$),
($q$Kyoto Gyoen weeping cherries$q$,$q$nature$q$,$q$Kyoto$q$,$q$Imperial Palace$q$,$q$The Imperial Palace park's early weeping cherries near the north side. Wide open, local, and good for a picnic.$q$,$q$Free$q$,array[$q$sakura$q$,$q$park$q$,$q$picnic$q$]::text[],35.0254,135.7621,$q$both$q$),
($q$Shimogamo Shrine & Tadasu no Mori$q$,$q$nature$q$,$q$Kyoto$q$,$q$Shimogamo$q$,$q$Ancient forest path leading to a vermilion shrine. Pair with mame-mochi from Demachi Futaba down the road.$q$,$q$Free$q$,array[$q$forest$q$,$q$shrine$q$,$q$traditional$q$,$q$walk$q$]::text[],35.039,135.772,$q$both$q$),
($q$Kurama to Kibune hike$q$,$q$nature$q$,$q$Kyoto$q$,$q$Kurama$q$,$q$Mountain trail over cedar roots from Kurama temple to the riverside village of Kibune, about 2 hours. Great half-day out of the city.$q$,$q$Cheap$q$,array[$q$hike$q$,$q$forest$q$,$q$onsen$q$,$q$temple$q$]::text[],35.118,135.771,$q$both$q$),
($q$Byodoin, Uji$q$,$q$sights$q$,$q$Kyoto$q$,$q$Uji$q$,$q$The Phoenix Hall on the ¥10 coin, reflected in its pond. Uji is Japan's matcha town, and the Nintendo Museum is here too, so it makes a perfect shared day.$q$,$q$~¥700$q$,array[$q$temple$q$,$q$traditional$q$,$q$tea-town$q$]::text[],34.8893,135.8077,$q$both$q$),
($q$Taihoan tea house, Uji$q$,$q$tea$q$,$q$Kyoto$q$,$q$Uji$q$,$q$City-run tea house by the Uji river, where you watch a tea master and then whisk your own matcha. Reserve at least three days ahead.$q$,$q$~¥2,400$q$,array[$q$tea$q$,$q$ceremony$q$,$q$booking$q$]::text[],34.8885,135.809,$q$sam$q$),
($q$Nakamura Tokichi, Uji$q$,$q$tea$q$,$q$Kyoto$q$,$q$Uji$q$,$q$Historic tea merchant (since 1854) in an old wooden building, famous for matcha jelly parfaits. Expect a queue at lunch.$q$,$q$~¥1,500$q$,array[$q$matcha$q$,$q$sweets$q$,$q$shop$q$]::text[],34.8925,135.8035,$q$sam$q$),
($q$Gion Tsujiri$q$,$q$tea$q$,$q$Kyoto$q$,$q$Gion$q$,$q$Matcha parfaits and soft serve from a tea company founded in 1860. A perfect afternoon reset in Gion.$q$,$q$~¥1,500$q$,array[$q$matcha$q$,$q$sweets$q$]::text[],35.0037,135.775,$q$both$q$),
($q$Gion Shirakawa at dusk$q$,$q$sights$q$,$q$Kyoto$q$,$q$Gion$q$,$q$Willow- and cherry-lined canal with wooden teahouses, prettiest as the lanterns come on. Please don't chase geiko for photos.$q$,$q$Free$q$,array[$q$traditional$q$,$q$sakura$q$,$q$walk$q$,$q$evening$q$]::text[],35.005,135.775,$q$both$q$),
($q$Maruyama Park weeping cherry$q$,$q$nature$q$,$q$Kyoto$q$,$q$Higashiyama$q$,$q$Kyoto's most famous single cherry tree, lit up at night, with food stalls and hanami parties all around.$q$,$q$Free$q$,array[$q$sakura$q$,$q$night$q$,$q$hanami$q$]::text[],35.0036,135.781,$q$both$q$),
($q$Sanjusangendo$q$,$q$sights$q$,$q$Kyoto$q$,$q$Higashiyama$q$,$q$A 120-metre wooden hall holding 1,001 golden statues of Kannon. Genuinely breathtaking.$q$,$q$~¥600$q$,array[$q$temple$q$,$q$statues$q$,$q$traditional$q$]::text[],34.988,135.772,$q$both$q$),
($q$Nishiki Market$q$,$q$food$q$,$q$Kyoto$q$,$q$Nakagyo$q$,$q$Covered market street of pickles, tofu, tamagoyaki and knives. Go before 10:30am to beat the crush. Eating while walking is discouraged, so eat at the stall.$q$,$q$Cheap$q$,array[$q$market$q$,$q$street-food$q$,$q$pickles$q$]::text[],35.005,135.765,$q$both$q$),
($q$Pontocho alley dinner$q$,$q$food$q$,$q$Kyoto$q$,$q$Pontocho$q$,$q$Narrow lantern-lit alley along the Kamo river packed with restaurants. Some have riverside platforms.$q$,$q$Mid–¥¥¥$q$,array[$q$dinner$q$,$q$alley$q$,$q$river$q$]::text[],35.006,135.771,$q$both$q$),
($q$Demachi Futaba mame-mochi$q$,$q$food$q$,$q$Kyoto$q$,$q$Demachi$q$,$q$Legendary sweet shop for mochi studded with salty beans. Locals queue happily for it.$q$,$q$~¥250$q$,array[$q$wagashi$q$,$q$sweets$q$,$q$queue$q$]::text[],35.03,135.772,$q$both$q$),
($q$Kissa Francois$q$,$q$coffee$q$,$q$Kyoto$q$,$q$Shijo$q$,$q$1934 European-style coffee house with velvet chairs, a stained-glass ceiling and classical music. Listed as a cultural property.$q$,$q$~¥700$q$,array[$q$kissaten$q$,$q$showa$q$,$q$cozy$q$]::text[],35.003,135.7695,$q$both$q$),
($q$Weekenders Coffee Tominokoji$q$,$q$coffee$q$,$q$Kyoto$q$,$q$Tominokoji$q$,$q$Tiny specialty roaster hidden in a car park courtyard behind a traditional facade. Some of Kyoto's best coffee.$q$,$q$~¥600$q$,array[$q$coffee$q$,$q$specialty$q$]::text[],35.006,135.764,$q$both$q$),
($q$Fushimi sake district$q$,$q$drinks$q$,$q$Kyoto$q$,$q$Fushimi$q$,$q$Old sake brewery quarter with willow-lined canals. Gekkeikan's museum has tastings, and there's a canal boat in spring. Pair with an early Fushimi Inari.$q$,$q$Cheap tastings$q$,array[$q$sake$q$,$q$brewery$q$,$q$canal$q$]::text[],34.931,135.761,$q$both$q$),
($q$Kyoto Brewing Co. taproom$q$,$q$drinks$q$,$q$Kyoto$q$,$q$Nishikujo$q$,$q$Kyoto's best-known craft brewery, with a taproom that usually opens weekends only. Check before going.$q$,$q$~¥1,000/glass$q$,array[$q$craft-beer$q$,$q$weekend$q$]::text[],34.985,135.744,$q$both$q$),
($q$Kyoto International Manga Museum$q$,$q$retro$q$,$q$Kyoto$q$,$q$Karasuma-Oike$q$,$q$Old school building with walls of 50,000 manga you can pull off the shelves and read on the lawn, plus history exhibits.$q$,$q$~¥1,200$q$,array[$q$manga$q$,$q$reading$q$,$q$retro$q$]::text[],35.0118,135.759,$q$both$q$),
($q$Kyoto Railway Museum$q$,$q$sights$q$,$q$Kyoto$q$,$q$Umekoji$q$,$q$Huge train museum with a working steam locomotive ride and the Shinkansen 0-series.$q$,$q$~¥1,500$q$,array[$q$trains$q$,$q$steam$q$,$q$museum$q$]::text[],34.987,135.743,$q$josh$q$),
($q$Nara Park deer$q$,$q$nature$q$,$q$Nara$q$,$q$Nara Park$q$,$q$1,000+ free-roaming sacred deer that bow for crackers. Walk a few minutes away from the cracker stands, where the deer are pushy, and feed one cracker at a time. Only feed them the official crackers.$q$,$q$Crackers ~¥200$q$,array[$q$deer$q$,$q$wildlife$q$,$q$daytrip$q$]::text[],34.685,135.843,$q$sam$q$),
($q$Todaiji$q$,$q$sights$q$,$q$Nara$q$,$q$Nara Park$q$,$q$One of the world's largest wooden buildings, home to a 15-metre bronze Buddha. Deer wander around the gate.$q$,$q$~¥800$q$,array[$q$temple$q$,$q$buddha$q$,$q$traditional$q$]::text[],34.689,135.8398,$q$both$q$),
($q$Kasuga Taisha lanterns$q$,$q$sights$q$,$q$Nara$q$,$q$Nara Park$q$,$q$Forest shrine lined with 3,000 stone and bronze lanterns, with deer drifting between them. Quietest early morning.$q$,$q$Free / ~¥700 inner area$q$,array[$q$shrine$q$,$q$lanterns$q$,$q$forest$q$,$q$deer$q$]::text[],34.6813,135.8485,$q$sam$q$),
($q$Yoshikien Garden$q$,$q$nature$q$,$q$Nara$q$,$q$Nara Park$q$,$q$Three small Japanese gardens (moss, pond and tea) next to Isuien. Free for foreign visitors with a passport, and often nearly empty.$q$,$q$Free for overseas visitors$q$,array[$q$garden$q$,$q$traditional$q$,$q$quiet$q$]::text[],34.686,135.835,$q$sam$q$),
($q$Wakakusayama at sunset$q$,$q$nature$q$,$q$Nara$q$,$q$Nara Park$q$,$q$Grassy hill above Nara Park with deer grazing and a view over the city at sunset. Usually opens for the season in mid-March.$q$,$q$~¥150$q$,array[$q$views$q$,$q$deer$q$,$q$sunset$q$]::text[],34.687,135.85,$q$sam$q$),
($q$Naramachi$q$,$q$coffee$q$,$q$Nara$q$,$q$Naramachi$q$,$q$Old merchant quarter of latticed wooden houses turned cafés, craft shops and a sake brewery. The calm part of Nara.$q$,$q$Cheap$q$,array[$q$old-town$q$,$q$cafes$q$,$q$cozy$q$]::text[],34.678,135.829,$q$both$q$),
($q$Nakanoshima Museum of Art$q$,$q$art$q$,$q$Osaka$q$,$q$Nakanoshima$q$,$q$Striking black-box museum opened in 2022 with modern art and design shows. The National Museum of Art Osaka is right next door.$q$,$q$Varies by show$q$,array[$q$art$q$,$q$design$q$,$q$architecture$q$]::text[],34.692,135.492,$q$sam$q$),
($q$Tower of the Sun, Expo '70 Park$q$,$q$art$q$,$q$Osaka$q$,$q$Suita$q$,$q$Taro Okamoto's giant, strange sculpture from Expo '70. You can go inside to see the 'Tree of Life' (book ahead). The park has lovely cherry blossom too.$q$,$q$~¥720 + park$q$,array[$q$art$q$,$q$retro$q$,$q$taro-okamoto$q$,$q$booking$q$]::text[],34.809,135.532,$q$sam$q$),
($q$Kitamura Camera, Namba$q$,$q$shopping$q$,$q$Osaka$q$,$q$Namba$q$,$q$Used film cameras in good condition that you can test in store, plus on-site colour film developing. In Namba CITY by Nankai Namba station.$q$,$q$Varies$q$,array[$q$film-camera$q$,$q$used$q$,$q$developing$q$]::text[],34.664,135.502,$q$sam$q$),
($q$Yaotomi Camera, Osaka Station$q$,$q$shopping$q$,$q$Osaka$q$,$q$Umeda$q$,$q$Used film cameras and binoculars near Osaka Station. A good second stop for film bodies.$q$,$q$Varies$q$,array[$q$film-camera$q$,$q$used$q$]::text[],34.702,135.496,$q$sam$q$),
($q$Osaka Mint cherry blossom passage$q$,$q$nature$q$,$q$Osaka$q$,$q$Temmabashi$q$,$q$The Mint opens its 560m avenue of late-blooming cherry varieties for about a week in early-mid April, which might line up with your Osaka days. Dates are announced in March.$q$,$q$Free (may need reservation)$q$,array[$q$sakura$q$,$q$late-bloom$q$,$q$limited-dates$q$]::text[],34.696,135.524,$q$both$q$),
($q$Osaka Castle Nishinomaru Garden$q$,$q$nature$q$,$q$Osaka$q$,$q$Osaka Castle$q$,$q$The castle's quieter paid garden lawn with about 600 cherry trees and the keep behind. Nice evening light-ups in season.$q$,$q$~¥200$q$,array[$q$sakura$q$,$q$castle$q$,$q$picnic$q$]::text[],34.6873,135.5262,$q$both$q$),
($q$Kitahama Retro$q$,$q$tea$q$,$q$Osaka$q$,$q$Kitahama$q$,$q$English-style tea room inside a tiny 1912 brick building by the river. Scones and afternoon tea in Osaka.$q$,$q$~¥1,500$q$,array[$q$tea$q$,$q$british$q$,$q$architecture$q$,$q$cozy$q$]::text[],34.6915,135.507,$q$sam$q$),
($q$Minoo Park waterfall$q$,$q$nature$q$,$q$Osaka$q$,$q$Minoh$q$,$q$An easy 3km forest walk to a 33-metre waterfall, with stalls selling deep-fried maple leaves. Wild monkeys live here too (don't feed them). Pair with Minoh Beer.$q$,$q$Free$q$,array[$q$hike$q$,$q$waterfall$q$,$q$monkeys$q$,$q$momiji-tempura$q$]::text[],34.853,135.472,$q$both$q$),
($q$Sumiyoshi Taisha$q$,$q$sights$q$,$q$Osaka$q$,$q$Sumiyoshi$q$,$q$One of Japan's oldest shrines, with a steep arched red bridge and a distinctive architectural style. Take the retro Hankai tram there.$q$,$q$Free$q$,array[$q$shrine$q$,$q$traditional$q$,$q$bridge$q$]::text[],34.6125,135.493,$q$both$q$),
($q$Tenma izakaya streets$q$,$q$food$q$,$q$Osaka$q$,$q$Tenma$q$,$q$Japan's longest shopping arcade plus a warren of cheap izakaya and standing bars around Tenma station. Where Osaka goes after work.$q$,$q$Cheap$q$,array[$q$izakaya$q$,$q$local$q$,$q$standing-bars$q$]::text[],34.705,135.512,$q$both$q$),
($q$Okonomiyaki Mizuno$q$,$q$food$q$,$q$Osaka$q$,$q$Dotonbori$q$,$q$Family-run okonomiyaki spot since 1945. The yam-batter version is the one. Worth the queue.$q$,$q$~¥1,500$q$,array[$q$okonomiyaki$q$,$q$queue$q$]::text[],34.6688,135.502,$q$both$q$),
($q$Rokko mountain drive, Kobe$q$,$q$drive$q$,$q$Osaka$q$,$q$Kobe$q$,$q$Twisting mountain roads above Kobe with one of Japan's famous night views. Pair with Kobe beef for dinner.$q$,$q$Small tolls$q$,array[$q$drive$q$,$q$night-view$q$,$q$needs-car$q$]::text[],34.76,135.23,$q$josh$q$),
($q$Okubiwako Parkway, Lake Biwa$q$,$q$drive$q$,$q$Kyoto$q$,$q$Shiga$q$,$q$Hilltop road on Lake Biwa's north shore lined with thousands of cherry trees, usually blooming in early-mid April. A blossom tunnel drive with lake views.$q$,$q$Free$q$,array[$q$drive$q$,$q$sakura$q$,$q$lake$q$,$q$needs-car$q$]::text[],35.53,136.17,$q$josh$q$),
($q$Booking calendar: the big ones$q$,$q$tip$q$,$q$Before you go$q$,null,$q$Set reminders. Yayoi Kusama Museum: 1 Jan / 1 Feb, 10am JST. Ghibli Park: 10 Feb, 2pm JST. Ghibli Museum: 10 March (via Lawson). Nintendo Museum: lottery months ahead. Toyota plant tour: 2 weeks to 3 months ahead. JDM rental cars: now.$q$,null,array[$q$admin$q$,$q$must-do$q$,$q$booking$q$]::text[],null,null,$q$both$q$),
($q$Japan Expressway Pass + ETC card$q$,$q$tip$q$,$q$Before you go$q$,null,$q$Foreign drivers can rent a flat-rate expressway pass with an ETC card from the rental company. It can save a lot on tolls across multi-day drives. Ask when booking the car.$q$,null,array[$q$admin$q$,$q$driving$q$,$q$tolls$q$]::text[],null,null,$q$josh$q$),
($q$Luggage forwarding (takkyubin)$q$,$q$tip$q$,$q$Before you go$q$,null,$q$Hotels and convenience stores can send your big bags ahead to the next hotel overnight. Essential when you're switching to a rental car or a small ryokan.$q$,$q$~¥2,000/bag$q$,array[$q$admin$q$,$q$luggage$q$]::text[],null,null,$q$both$q$),
($q$Sakura forecast$q$,$q$tip$q$,$q$Before you go$q$,null,$q$Tokyo usually peaks late March to early April, and Kyoto and Osaka a few days later. Watch the Japan Meteorological Corporation forecast from February and shuffle hanami plans to match.$q$,null,array[$q$sakura$q$,$q$planning$q$]::text[],null,null,$q$both$q$),
($q$IC card on your phone$q$,$q$tip$q$,$q$Before you go$q$,null,$q$Add a Suica or PASMO to Apple Wallet before you fly. It works on trains, buses, convenience stores and lockers everywhere on your route.$q$,null,array[$q$admin$q$,$q$transport$q$]::text[],null,null,$q$both$q$),
($q$Cash & 7-Eleven ATMs$q$,$q$tip$q$,$q$Before you go$q$,null,$q$Plenty of small bars, temples and kissaten are cash-only. 7-Eleven ATMs take foreign cards reliably, so keep ¥10–20k on you.$q$,null,array[$q$admin$q$,$q$money$q$]::text[],null,null,$q$both$q$),
($q$Yamaha Communication Plaza$q$,$q$cars$q$,$q$Shizuoka$q$,$q$Iwata$q$,$q$Yamaha Motor's museum with GP bikes, classic motorcycles and the engines Yamaha built for Toyota (2000GT, LFA). It's right on the route between Hakone and Nagoya. Check opening days.$q$,$q$Free$q$,array[$q$museum$q$,$q$yamaha$q$,$q$bikes$q$,$q$needs-car$q$]::text[],34.723,137.856,$q$josh$q$),
($q$Suzuki Plaza$q$,$q$cars$q$,$q$Shizuoka$q$,$q$Hamamatsu$q$,$q$Suzuki's history museum: looms to kei cars, Hayabusas and a mini factory line. Reserve a slot online. Pairs with Yamaha the same day.$q$,$q$Free, book ahead$q$,array[$q$museum$q$,$q$suzuki$q$,$q$kei-cars$q$]::text[],34.711,137.723,$q$josh$q$),
($q$Kawasaki Good Times World$q$,$q$cars$q$,$q$Osaka$q$,$q$Kobe Harborland$q$,$q$Kawasaki's showcase by Kobe's harbour, with Ninjas, race bikes, a 0-series Shinkansen nose and helicopters. Easy add-on to a Rokko drive.$q$,$q$~¥900$q$,array[$q$museum$q$,$q$kawasaki$q$,$q$bikes$q$,$q$shinkansen$q$]::text[],34.68,135.188,$q$josh$q$),
($q$Mazda Museum, Hiroshima$q$,$q$cars$q$,$q$Osaka$q$,$q$Hiroshima (day trip)$q$,$q$Rotary history (Cosmo, RX-7s, the Le Mans 787B) plus a look at the real assembly line. It's 1.5 hours from Osaka by Shinkansen. Combine with Miyajima for Sam.$q$,$q$Free, booking required$q$,array[$q$museum$q$,$q$mazda$q$,$q$rotary$q$,$q$daytrip$q$]::text[],34.37,132.5,$q$josh$q$),
($q$Miyajima (Itsukushima)$q$,$q$nature$q$,$q$Osaka$q$,$q$Hiroshima (day trip)$q$,$q$Island of friendly deer and the floating torii gate, with maple-leaf cakes on the high street. The deer here aren't fed crackers, so keep food away from them. Pairs with the Mazda Museum.$q$,$q$Ferry ~¥200 + visitor tax$q$,array[$q$deer$q$,$q$shrine$q$,$q$island$q$,$q$daytrip$q$]::text[],34.296,132.319,$q$sam$q$),
($q$Yamazaki Distillery$q$,$q$drinks$q$,$q$Kyoto$q$,$q$Shimamoto$q$,$q$Suntory's first whisky distillery, between Kyoto and Osaka. Tour slots open online and vanish in minutes, so set a reminder. The tasting bar has rare pours.$q$,$q$Tour ~¥3,000, book far ahead$q$,array[$q$whisky$q$,$q$booking$q$,$q$must-book$q$]::text[],34.892,135.674,$q$both$q$),
($q$Hakutsuru Sake Brewery Museum$q$,$q$drinks$q$,$q$Osaka$q$,$q$Kobe (Nada)$q$,$q$Old brewery in Kobe's Nada sake district showing traditional brewing, with free tastings at the end. Other breweries are walkable nearby.$q$,$q$Free$q$,array[$q$sake$q$,$q$museum$q$,$q$tasting$q$]::text[],34.713,135.26,$q$both$q$),
($q$Shinjuku Golden Gai$q$,$q$drinks$q$,$q$Tokyo$q$,$q$Shinjuku$q$,$q$Six alleys of 200 bars that seat five to eight people each. Touristy now, but still magic. Pick one with a theme you love, like punk, film or horror, and check the cover charge on the door.$q$,$q$Cover ¥500–1,000 + drinks$q$,array[$q$bars$q$,$q$tiny$q$,$q$night$q$]::text[],35.694,139.7046,$q$both$q$),
($q$Baird Beer Harajuku Taproom$q$,$q$drinks$q$,$q$Tokyo$q$,$q$Harajuku$q$,$q$Taproom of one of Japan's pioneering craft brewers, with yakitori-style bar food, just off Takeshita Street's chaos.$q$,$q$~¥1,000/pint$q$,array[$q$craft-beer$q$,$q$izakaya$q$]::text[],35.67,139.705,$q$both$q$),
($q$Disk Union Shinjuku$q$,$q$retro$q$,$q$Tokyo$q$,$q$Shinjuku$q$,$q$Cluster of genre-specific record shops across several floors and buildings. City pop and old anime soundtracks on vinyl are the souvenirs.$q$,$q$Varies$q$,array[$q$records$q$,$q$vinyl$q$,$q$city-pop$q$,$q$shop$q$]::text[],35.6915,139.704,$q$both$q$),
($q$Mandarake Grand Chaos, Osaka$q$,$q$retro$q$,$q$Osaka$q$,$q$Shinsaibashi$q$,$q$Osaka's big Mandarake with vintage toys, retro games, cels and figures. A good rainy-day dig near Amerikamura.$q$,$q$Free to browse$q$,array[$q$games$q$,$q$toys$q$,$q$collectors$q$]::text[],34.672,135.499,$q$josh$q$),
($q$Kobe beef lunch$q$,$q$food$q$,$q$Osaka$q$,$q$Kobe (Sannomiya)$q$,$q$Teppanyaki lunch sets are far better value than dinner. Look for the certified Kobe beef bronze statue logo. Book ahead.$q$,$q$~¥5,000–10,000$q$,array[$q$kobe-beef$q$,$q$teppanyaki$q$,$q$lunch$q$]::text[],34.693,135.195,$q$both$q$),
($q$AFURI ramen$q$,$q$food$q$,$q$Tokyo$q$,$q$Harajuku$q$,$q$Light, citrusy yuzu shio ramen. A great first ramen when it's warm or you're jet-lagged.$q$,$q$~¥1,300$q$,array[$q$ramen$q$,$q$yuzu$q$]::text[],35.671,139.707,$q$both$q$),
($q$Ramen Jiro (Mita main shop)$q$,$q$food$q$,$q$Tokyo$q$,$q$Mita$q$,$q$Cult-status mountain of noodles, pork, garlic and bean sprouts. There are rules: buy a ticket, order toppings when asked, eat fast, leave. An experience.$q$,$q$~¥900$q$,array[$q$ramen$q$,$q$challenge$q$,$q$queue$q$]::text[],35.646,139.744,$q$josh$q$),
($q$Uobei conveyor sushi$q$,$q$food$q$,$q$Tokyo$q$,$q$Shibuya$q$,$q$Touch-screen sushi that arrives on bullet-train lanes. Cheap, fast and fun in Shibuya.$q$,$q$~¥1,500$q$,array[$q$sushi$q$,$q$cheap$q$,$q$fun$q$]::text[],35.659,139.699,$q$both$q$),
($q$Moomin Valley Park$q$,$q$sights$q$,$q$Tokyo$q$,$q$Hanno (Saitama)$q$,$q$Lakeside forest park with the Moomin house, shows and Nordic cafés. Slow and sweet, about an hour from Ikebukuro.$q$,$q$~¥3,600$q$,array[$q$moomin$q$,$q$lake$q$,$q$kawaii$q$,$q$daytrip$q$]::text[],35.864,139.317,$q$sam$q$),
($q$Kurosuke's House, Totoro Forest$q$,$q$sights$q$,$q$Tokyo$q$,$q$Tokorozawa (Saitama)$q$,$q$Old farmhouse in the Sayama Hills, the woods that inspired My Neighbour Totoro, run by the Totoro Forest Foundation. Open only a few days a week, so check before going.$q$,$q$Free$q$,array[$q$ghibli$q$,$q$totoro$q$,$q$forest$q$,$q$limited-days$q$]::text[],35.781,139.422,$q$sam$q$),
($q$Shibamata & Tora-san Museum$q$,$q$sights$q$,$q$Tokyo$q$,$q$Katsushika$q$,$q$Showa-era temple town from the long-running Tora-san film series: a museum with the film sets, a street of dango shops, and Taishakuten temple's incredible wood carvings.$q$,$q$~¥500$q$,array[$q$film$q$,$q$showa$q$,$q$temple$q$,$q$old-tokyo$q$]::text[],35.758,139.877,$q$sam$q$),
($q$Higashiya Ginza$q$,$q$tea$q$,$q$Tokyo$q$,$q$Ginza$q$,$q$Modern wagashi tea salon with beautiful seasonal sweets and tea pairings. Calm, design-led and very Sam.$q$,$q$~¥2,000$q$,array[$q$tea$q$,$q$wagashi$q$,$q$design$q$]::text[],35.672,139.765,$q$sam$q$),
($q$Kintsugi workshop$q$,$q$art$q$,$q$Tokyo$q$,$q$Various$q$,$q$Mend a broken bowl with lacquer and gold. Several Tokyo studios run English classes of 2–3 hours, and some let you take the piece home unfinished to cure. Book ahead.$q$,$q$~¥5,000–10,000$q$,array[$q$kintsugi$q$,$q$hands-on$q$,$q$traditional$q$,$q$booking$q$]::text[],null,null,$q$sam$q$),
($q$Itoya Ginza$q$,$q$shopping$q$,$q$Tokyo$q$,$q$Ginza$q$,$q$Twelve floors of stationery, with washi paper, fountain pens, letter-writing desks and a hydroponic lettuce farm near the top. Dangerous for a stationery lover.$q$,$q$Varies$q$,array[$q$stationery$q$,$q$paper$q$,$q$shop$q$]::text[],35.672,139.768,$q$sam$q$),
($q$Kyukyodo, Kyoto$q$,$q$shopping$q$,$q$Kyoto$q$,$q$Teramachi$q$,$q$Incense and washi paper shop dating to 1663. Beautiful postcards, letter sets and incense to take home.$q$,$q$Varies$q$,array[$q$incense$q$,$q$paper$q$,$q$traditional$q$,$q$shop$q$]::text[],35.012,135.7675,$q$sam$q$),
($q$Otagi Nenbutsu-ji$q$,$q$sights$q$,$q$Kyoto$q$,$q$Arashiyama (Okusaga)$q$,$q$Mossy hillside with 1,200 little stone rakan statues carved by amateurs, each with its own face, some laughing and one holding a camera. Far quieter than central Arashiyama.$q$,$q$~¥300$q$,array[$q$temple$q$,$q$statues$q$,$q$quirky$q$,$q$quiet$q$]::text[],35.03,135.665,$q$sam$q$),
($q$Kamogawa Delta turtle stones$q$,$q$nature$q$,$q$Kyoto$q$,$q$Demachiyanagi$q$,$q$Hop across the river on turtle-shaped stepping stones where the two rivers meet. Take a beer or a bento and sit on the bank.$q$,$q$Free$q$,array[$q$river$q$,$q$picnic$q$,$q$sakura$q$,$q$fun$q$]::text[],35.03,135.772,$q$both$q$),
($q$Yoyogi Park hanami$q$,$q$nature$q$,$q$Tokyo$q$,$q$Harajuku$q$,$q$Where Tokyo actually does hanami: tarps, beers and music under the trees. Bring a picnic sheet from a konbini.$q$,$q$Free$q$,array[$q$sakura$q$,$q$picnic$q$,$q$hanami$q$,$q$people-watching$q$]::text[],35.672,139.695,$q$both$q$),
($q$Meguro River at night$q$,$q$nature$q$,$q$Tokyo$q$,$q$Nakameguro$q$,$q$Canal lined with cherry trees lit with lanterns. It's very busy at peak, so go late on a weeknight with a strawberry sparkling wine from a stall. Nakameguro's cafés are around it.$q$,$q$Free$q$,array[$q$sakura$q$,$q$night$q$,$q$busy$q$]::text[],35.644,139.699,$q$both$q$);
